<script setup lang="ts">
import { ref, onMounted } from 'vue'
import { settings, byteLabel } from '@/composables/useSettings'
import { toast } from '@/composables/useToasts'
import { errorMessage } from '@/domain/validation'
import PageHeading from '@/components/PageHeading.vue'
import AppIcon from '@/components/AppIcon.vue'
import NoticeBox from '@/components/NoticeBox.vue'
const storage = ref<{ usage?: number; quota?: number }>({}), persistent = ref(false), busy = ref(false)
async function refresh(): Promise<void> { try { storage.value = await navigator.storage?.estimate() || {}; persistent.value = await navigator.storage?.persisted?.() || false } catch { /* Advisory only. */ } }
async function persist(): Promise<void> { busy.value = true; try { persistent.value = await navigator.storage?.persist?.() || false; toast(persistent.value ? 'Persistent browser storage was granted. Keep external backups too.' : 'This browser did not grant persistence. Export important projects regularly.', persistent.value ? 'success' : 'warning') } catch (e) { toast(errorMessage(e), 'error') } finally { busy.value = false; await refresh() } }
onMounted(refresh)
</script>
<template><div class="container settings-wrapper narrow"><PageHeading eyebrow="MAKE YOURSELF AT HOME" title="A workspace that feels like you." subtitle="Preferences apply to this device. No cloud profile is created."/><div class="card settings-card"><h2>Look & feel</h2><div class="single-settings"><div class="title"><AppIcon name="sun"/><span><strong>Appearance</strong><small>Choose a comfortable canvas.</small></span></div><select v-model="settings.theme" class="form-select" aria-label="Appearance"><option value="system">Use device setting</option><option value="light">Light</option><option value="dark">Dark</option></select></div><div class="single-settings"><div class="title"><AppIcon name="spark"/><span><strong>Reduce motion</strong><small>Disable non-essential animation.</small></span></div><div class="data-content"><label class="toggle-button-cover"><span class="visually-hidden">Reduce motion</span><span class="button r"><input v-model="settings.reduceMotion" type="checkbox" class="checkbox" role="switch"><span class="knobs"/><span class="layer"/></span></label></div></div></div><div class="card settings-card"><h2>Capture & viewing</h2><div class="single-settings"><div class="title"><AppIcon name="ruler"/><span><strong>Display units</strong><small>Geometry always stays in metres internally.</small></span></div><select v-model="settings.units" class="form-select" aria-label="Display units"><option value="m">Metres</option><option value="ft">Feet</option></select></div><div class="single-settings"><div class="title"><AppIcon name="scan"/><span><strong>Capture budget</strong><small>Higher detail uses more memory.</small></span></div><select v-model="settings.quality" class="form-select" aria-label="Capture quality"><option value="balanced">Balanced</option><option value="detail">Detail</option></select></div><div class="single-settings"><div class="title"><AppIcon name="grid"/><span><strong>Viewer ground grid</strong><small>Show a visual scale reference.</small></span></div><label class="toggle-button-cover"><span class="visually-hidden">Viewer ground grid</span><span class="button r"><input v-model="settings.grid" type="checkbox" class="checkbox" role="switch"><span class="knobs"/><span class="layer"/></span></label></div></div><div class="card settings-card"><h2>Keep your work safe</h2><div class="stat-pair"><span>Origin storage used</span><strong>{{ storage.usage !== undefined ? byteLabel(storage.usage) : 'Unavailable' }}</strong></div><div class="stat-pair"><span>Reported quota</span><strong>{{ storage.quota !== undefined ? byteLabel(storage.quota) : 'Unavailable' }}</strong></div><div class="stat-pair"><span>Browser persistence</span><strong>{{ persistent ? 'Granted' : 'Not granted' }}</strong></div><p class="fine-print">Quota is a browser estimate, not guaranteed free space. Clearing site data or uninstalling the app can remove projects and recovery captures.</p><button class="btn btn-outline-primary w-100" :disabled="busy || persistent" @click="persist"><AppIcon name="shield" :size="18"/>{{ persistent ? 'Persistence is enabled' : busy ? 'Requesting…' : 'Request persistent storage' }}</button><RouterLink to="/library" class="settings-link">Export project backups<AppIcon name="chevron" :size="18"/></RouterLink><RouterLink to="/import" class="settings-link">Restore a W3D backup<AppIcon name="chevron" :size="18"/></RouterLink></div><NoticeBox>Your device storage is not an encrypted application vault. Use your device lock, protect shared devices, and choose encrypted W3D exports for sensitive spaces.</NoticeBox><div class="card settings-card"><RouterLink to="/device" class="settings-link"><span><AppIcon name="phone" :size="20"/>Device compatibility</span><AppIcon name="chevron" :size="18"/></RouterLink><RouterLink to="/privacy" class="settings-link"><span><AppIcon name="shield" :size="20"/>Privacy & permissions</span><AppIcon name="chevron" :size="18"/></RouterLink><RouterLink to="/guide" class="settings-link"><span><AppIcon name="help" :size="20"/>Help & scanning guide</span><AppIcon name="chevron" :size="18"/></RouterLink><div class="version-label">Three Dimension View · v1.0.0<br>Vue SPA · Suha-based interface · native capture adapters</div></div></div></template>
